def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        count = 1
        i += 1
        while i < n and texto[i] == ch:
            count += 1
            i += 1
        result.append(f"{ch}{count}")
    return "".join(result)

def iniciales(nombre: str) -> str:
    words = nombre.split()
    if not words:
        return ""
    return ''.join(word[0].upper() for word in words)

def es_palindromo(texto: str) -> bool:
    filtrado = ''.join(ch.lower() for ch in texto if ch.isalnum())
    return filtrado == filtrado[::-1]

def aplanar(datos):
    def flatten(obj):
        if isinstance(obj, list):
            result = []
            for item in obj:
                result.extend(flatten(item))
            return result
        elif isinstance(obj, tuple):
            result = []
            for item in obj:
                result.extend(flatten(item))
            return result
        else:
            return [obj]
    return flatten(datos)

import csv
import io

def parsear_ventas(texto: str) -> list[dict]:
    if not texto or not texto.strip():
        return []
    reader = csv.reader(io.StringIO(texto), delimiter=',', quotechar='"')
    rows = list(reader)
    non_empty_rows = []
    for row in rows:
        if len(row) == 0:
            continue
        if len(row) != 4:
            raise ValueError(f"Fila con número incorrecto de campos: {row}")
        non_empty_rows.append(row)
    if not non_empty_rows:
        return []
    header = non_empty_rows[0]
    expected_header = ['fecha', 'producto', 'cantidad', 'precio']
    if header != expected_header:
        raise ValueError("Cabecera no es la indicada")
    data_rows = non_empty_rows[1:]
    result = []
    for row in data_rows:
        try:
            cantidad = int(row[2].strip())
        except ValueError:
            raise ValueError(f"Cantidad no es un entero: {row[2]}")
        if cantidad < 0:
            raise ValueError(f"Cantidad negativa: {row[2]}")
        try:
            precio = float(row[3].strip())
        except ValueError:
            raise ValueError(f"Precio no es un número: {row[3]}")
        result.append({
            'fecha': row[0],
            'producto': row[1],
            'cantidad': cantidad,
            'precio': precio
        })
    return result

import datetime

def parsear_fecha(texto: str) -> str:
    texto = texto.strip()

    # Formato ISO: AAAA-MM-DD
    if '-' in texto and '/' not in texto and ' de ' not in texto:
        try:
            dt = datetime.datetime.strptime(texto, "%Y-%m-%d")
            return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}"
        except ValueError:
            pass

    # Formato DD/MM/AAAA
    elif '/' in texto and ' de ' not in texto:
        try:
            dt = datetime.datetime.strptime(texto, "%d/%m/%Y")
            return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}"
        except ValueError:
            pass

    # Formato D de MES de AAAA
    elif ' de ' in texto:
        parts = texto.split(' de ')
        if len(parts) != 3:
            raise ValueError("Formato inválido para fecha de mes")
        day_str = parts[0].strip()
        month_str = parts[1].strip()
        year_str = parts[2].strip()
        try:
            day = int(day_str)
        except ValueError:
            raise ValueError(f"Día no válido: {day_str}")
        try:
            year = int(year_str)
        except ValueError:
            raise ValueError(f"Año no válido: {year_str}")
        month_map = {
            "enero": 1,
            "febrero": 2,
            "marzo": 3,
            "abril": 4,
            "mayo": 5,
            "junio": 6,
            "julio": 7,
            "agosto": 8,
            "septiembre": 9,
            "octubre": 10,
            "noviembre": 11,
            "diciembre": 12,
        }
        month_name = month_str.lower().strip()
        if month_name not in month_map:
            raise ValueError(f"Mes no reconocido: {month_str}")
        month = month_map[month_name]
        try:
            dt = datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Fecha inválida: {texto}")
        return f"{year:04d}-{month:02d}-{day:02d}"

    else:
        raise ValueError("Formato no reconocido")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must match")
    if any(p < 0 for p in pesos) or capacidad < 0:
        raise ValueError("Weights or capacity cannot be negative")
    n = len(pesos)
    if n == 0:
        return (0, [])
    best = None
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight > capacidad:
            continue
        candidate = (total_value, total_weight, len(indices), indices)
        if best is None:
            best = candidate
        else:
            if (candidate[0] > best[0]) or \
               (candidate[0] == best[0] and candidate[1] < best[1]) or \
               (candidate[0] == best[0] and candidate[1] == best[1] and candidate[2] < best[2]) or \
               (candidate[0] == best[0] and candidate[1] == best[1] and candidate[2] == best[2] and candidate[3] < best[3]):
                best = candidate
    if best is None:
        return (0, [])
    else:
        return (best[0], best[3])

def evaluar(expresion: str) -> int:
    s = expresion.replace(" ", "")
    if '**' in s:
        raise ValueError("Invalid operator: exponent")
    elif '//' in s:
        # allowed
        pass
    elif '/' in s:
        raise ValueError("Invalid operator: division")
    elif s.startswith('+'):
        raise ValueError("Invalid expression: unary plus")
    else:
        # no slash or double slash
        pass
    try:
        result = eval(s)
    except ZeroDivisionError:
        raise ZeroDivisionError("division by zero")
    except Exception as e:
        raise ValueError("Invalid expression") from e
    return result

from collections import OrderedDict

class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            value = self._datos[clave]
            self._datos.move_to_end(clave, last=True)
            return value
        return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave not in self._datos and len(self._datos) >= self.capacidad:
            self._datos.popitem(last=False)
        self._datos[clave] = valor
        self._datos.move_to_end(clave, last=True)

    def __len__(self):
        return len(self._datos)
